function extractText(parts) {
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body?.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf-8');
    }
    if (part.parts) {
      const result = extractText(part.parts);
      if (result) return result;
    }
  }
  return null;
}

const item = $input.first().json;
const messageId = item.id;
const payload = item.payload;
const parts = payload?.parts || [];

let mailText = extractText(parts);
if (!mailText) {
  mailText = item.snippet || '';
}

const pdfPart = parts.find(p =>
  p.filename &&
  p.filename.toLowerCase().endsWith('.pdf') &&
  p.body?.attachmentId
);

const hasAttachment = !!pdfPart;
const attachmentId = hasAttachment ? pdfPart.body.attachmentId : null;
const filename = hasAttachment ? pdfPart.filename : null;

return [{
  json: {
    messageId,
    mailText,
    hasAttachment,
    attachmentId,
    filename
  }
}];

const base64 = $input.first().json.data;
// Gmail uses URL-safe base64
const standard = base64.replace(/-/g, '+').replace(/_/g, '/');
const buffer = Buffer.from(standard, 'base64');

const messageId = $('Extract Email').first().json.messageId;
const filename = $('Extract Email').first().json.filename || 'attachment.pdf';

return [{
  json: { messageId },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: filename,
      fileExtension: 'pdf'
    }
  }
}];

const pdfText = ($input.first().json.text || '').substring(0, 20000);
const extracted = $('Extract Email').first().json;

return [{
  json: {
    messageId: extracted.messageId,
    mailText: extracted.mailText + '\n\n--- PDF CONTENT ---\n\n' + pdfText
  }
}];

const output = $input.first().json.output;
const jsonMatch = output.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('No JSON found in output');
const parsed = JSON.parse(jsonMatch[0]);

parsed.messageId = $('Extract Email').first().json.messageId;

return [{ json: parsed }];
